`,(0,n.jsxs)(o,{children:[(0,n.jsx)(r.p,{children:"I've researched knee-strengthening exercises from physical therapy sources and created a complete routine for you."}),(0,n.jsx)(r.p,{children:(0,n.jsx)(r.strong,{children:"Research Summary"})}),(0,n.jsx)(r.p,{children:"Based on current PT guidance for medial knee pain, I found exercises targeting the quadriceps, hamstrings, and hip stabilizers—all crucial for knee support. These are specifically chosen to be low-impact and safe for people with existing knee discomfort when done with proper form."}),(0,n.jsx)(r.p,{children:(0,n.jsx)(r.strong,{children:'✓ Saved to Apple Notes as "Knee Strengthening Routine"'})}),(0,n.jsx)(r.p,{children:"Your routine is ready to pull up on your phone. It includes 6 low-impact exercises targeting quads, hamstrings, and supporting muscles, with a warm-up and cool-down. Everything's abbreviated and formatted for quick reference while you're exercising."}),(0,n.jsx)(r.p,{children:"The routine starts conservatively (3× weekly) with built-in progression for weeks 3-5+. I included a checkbox for your PT appointment date so you can fill that in."})]}),`
